import React from "react";
import Sidebar from "./Sidebar";

const Layout = ({ children }) => {
  // بررسی کن که آیا کاربر لاگین کرده یا نه
  const isAuthenticated = !!localStorage.getItem("token");

  if (!isAuthenticated) {
    // اگر لاگین نکرده، فقط محتوای اصلی را نمایش بده (بدون سایدبار)
    return <div>{children}</div>;
  }

  // اگر لاگین کرده، سایدبار هم نمایش داده شود
  return (
    <div className="d-flex" style={{ height: "100vh" }}>
      {/* Sidebar ثابت در سمت چپ */}
      <Sidebar />

      {/* بخش اصلی (main content) */}
      <div
        className="flex-grow-1 bg-white p-4"
        style={{ overflowY: "auto", minWidth: 0 }}
      >
        {children}
      </div>
    </div>
  );
};

export default Layout;
